import org.apache.kafka.streams.*;
import org.apache.kafka.streams.kstream.*;
import java.time.Duration;
import java.util.Properties;

public class OrderMetrics {
  public static void main(String[] args) {
    Properties props = new Properties();
    props.put(StreamsConfig.APPLICATION_ID_CONFIG, "order-metrics");   // == consumer group id
    props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
    props.put(StreamsConfig.PROCESSING_GUARANTEE_CONFIG,
              StreamsConfig.EXACTLY_ONCE_V2);                          // atomic state+output+offsets
    props.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG,
              Serdes.String().getClass());
    props.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG,
              Serdes.String().getClass());

    StreamsBuilder builder = new StreamsBuilder();

    // Source: append-only event stream
    KStream<String, String> orders = builder.stream("orders");

    orders
        .filter((orderId, value) -> !value.contains("\"test\":true"))  // stateless
        .selectKey((orderId, value) -> extractCustomerId(value))       // re-key -> repartition
        .groupByKey()
        .windowedBy(TimeWindows.ofSizeAndGrace(
              Duration.ofMinutes(1), Duration.ofSeconds(10)))          // tumbling + grace
        .count(Materialized.as("orders-per-customer-1m"))              // stateful, RocksDB store
        .toStream()
        .map((windowedKey, cnt) ->
              KeyValue.pair(windowedKey.key(), Long.toString(cnt)))
        .to("orders-per-customer-1m");                                 // sink topic

    KafkaStreams streams = new KafkaStreams(builder.build(), props);
    Runtime.getRuntime().addShutdownHook(new Thread(streams::close));
    streams.start();
  }

  static String extractCustomerId(String json) {
    // real code would parse JSON; simplified for illustration
    int i = json.indexOf("customer_id");
    return json.substring(i + 14, json.indexOf('"', i + 14));
  }
}
